PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?amount)) AS ?averageDividendCashFlow)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "dividend"^^xsd:string ;
            ex:amount ?amount .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(xsd:date(?purchaseDate)) AS ?earliestPurchaseDate)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (AVG(xsd:decimal(?holdingDuration)) AS ?averageHoldingDuration)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName ;
            ex:hasHolding ?holding .

  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate ;
           ex:currentValue ?currentValue .

  # Calculate holding duration in days
  BIND(DATEDIFF(?purchaseDate, "2023-10-01") AS ?holdingDuration)
}
GROUP BY ?investorName
ORDER BY DESC(?averageHoldingDuration)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year (MAX(xsd:decimal(?totalInvestment)) AS ?highestInvestment)
WHERE {
  VALUES ?year { "2022"^^xsd:string "2023"^^xsd:string "2024"^^xsd:string }
  ?allocation a ex:SectorAllocation ;
              ex:totalInvestment ?totalInvestment ;
              ex:hasInvestor [ ex:purchaseDate ?date ] .
  FILTER (CONTAINS(?date, ?year))
}
GROUP BY ?year
ORDER BY DESC(?highestInvestment)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?currentValue)) AS ?totalPortfolioValue)
WHERE {
  ?investorProfile a ex:InvestorProfile ;
                   ex:riskTolerance "Conservative" .
  ?portfolioHolding a ex:PortfolioHolding ;
                    ex:hasInvestor ?investorProfile ;
                    ex:currentValue ?currentValue .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLiteral (AVG(xsd:decimal(?taxesPaid)) AS ?averageTaxesPaid)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:categoryLiteral ?categoryLiteral ;
                     ex:taxesPaid ?taxesPaid .
}
GROUP BY ?categoryLiteral

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
WHERE {
  ?investorProfile ex:investorId "INV-010" ;
                    ex:hasHolding ?portfolioHolding .
  ?portfolioHolding ex:investmentTypeLiteral "ETF" ;
                     ex:currentValue ?currentValue .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?goldHolding) AS ?goldHoldingsCount)
WHERE {
  ?investorProfile ex:investorId "INV-005" ;
                    ex:hasHolding ?portfolioHolding .
  ?portfolioHolding ex:investmentTypeLiteral "Gold" .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "Dividend" ;
            ex:source "HDFC Bank" ;
            ex:hasInvestor ?investorProfile .
  ?investorProfile a ex:InvestorProfile ;
                   ex:notes ?investorName .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?date ?amount
WHERE {
  ?cashFlow ex:date ?date ;
            ex:cashFlowType "Redemption" ;
            ex:amount ?amount ;
            ex:hasInvestor ?investor .
  ?investor ex:investorId "inv-008" .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  ?sectorName
  (COUNT(?rebalancingAction) AS ?numberOfRebalancingActions)
  ((SUM(xsd:decimal(?currentAllocationPct)) - SUM(xsd:decimal(?targetAllocationPct))) AS ?deviationFromTarget)

WHERE {
  ?rebalancingAction a ex:RebalancingAction ;
    ex:hasInvestor ?investor ;
    ex:currentAllocationPct ?currentAllocationPct ;
    ex:targetAllocationPct ?targetAllocationPct .

  ?sectorAllocation a ex:SectorAllocation ;
    ex:hasInvestor ?investor ;
    ex:sectorName ?sectorName .
}

GROUP BY ?sectorName

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?date (SUM(xsd:decimal(?amount)) AS ?totalAmount)
WHERE {
  ?cashFlow a ex:CashFlow ;
             ex:date ?date ;
             ex:hasInvestor ?investor ;
             ex:amount ?amount .
  FILTER(CONTAINS(LCASE(STR(?investor)), "inv-003"))
}
GROUP BY ?date
ORDER BY ?date

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalId ?avgSharpeRatio
WHERE {
  ?investmentGoal ex:goalId "G003"^^xsd:string ;
                   ex:avgSharpeRatio ?avgSharpeRatio .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentTypeLiteral (AVG(xsd:decimal(?cost)) AS ?averageCost)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:hasInvestmentType ?investmentType ;
                     ex:cost ?cost .
  ?investmentType ex:investmentTypeName ?investmentTypeLiteral .
}
GROUP BY ?investmentTypeLiteral

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?goldHolding) AS ?goldHoldingsCount)
WHERE {
  ?investorProfile ex:investorId "INV-005" ;
                    ex:hasHolding ?portfolioHolding .
  ?portfolioHolding ex:categoryLiteral "Gold" .
