PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?returnsPct
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:purchaseDate ?purchaseDate ;
                     ex:investmentName ?investmentName ;
                     ex:returnsPct ?returnsPct .

  FILTER(CONTAINS(LCASE(?purchaseDate), "2024"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (MIN(xsd:date(?purchaseDate)) AS ?earliestPurchaseDate)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (STRFTIME("%Y-%m", ?date) AS ?month) (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
WHERE {
  ?cashFlow ex:date ?date ;
            ex:amount ?amount ;
            ex:hasInvestor ?investor .
  ?investor ex:investorId "INV003"^^xsd:string .
}
GROUP BY STRFTIME("%Y-%m", ?date)
ORDER BY ?month

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (AVG(xsd:decimal(?holdingDuration)) AS ?averageHoldingDuration)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName ;
            ex:hasHolding ?holding .

  ?holding a ex:PortfolioHolding ;
           ex:purchaseDate ?purchaseDate ;
           ex:currentValue ?currentValue .

  # Calculate holding duration in days
  BIND(DATEDIFF(?purchaseDate, "2023-10-01") AS ?holdingDuration)
}
GROUP BY ?investorName
ORDER BY ASC(?averageHoldingDuration)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (YEAR(?purchaseDate) AS ?year) (COUNT(?holdingId) AS ?holdingsCount)
WHERE {
  ?investor ex:hasHolding ?portfolioHolding .
  ?portfolioHolding ex:hasInvestor ?investor ;
                     ex:purchaseDate ?purchaseDate ;
                     ex:holdingId ?holdingId .
  ?investor ex:investorName ?investorName .
}
GROUP BY ?investorName (YEAR(?purchaseDate))

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?source (COUNT(?cashFlowId) AS ?transactionCount)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:source ?source ;
            ex:cashFlowId ?cashFlowId .
}
GROUP BY ?source
ORDER BY DESC(?transactionCount)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?cashFlow) AS ?redemptionCount)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "Redemption" ;
            ex:hasInvestor ?investor .
  FILTER(CONTAINS(LCASE(STR(?investor)), "inv-008"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?sectorFocus ?highestAllocatedSector
WHERE {
  ?investorProfile ex:investorId "inv-001" ;
                    ex:sectorFocus ?sectorFocus .

  ?allocation ex:hasInvestor ?investorProfile ;
              ex:sectorName ?highestAllocatedSector ;
              ex:allocationPct ?allocationPct .

  FILTER NOT EXISTS {
    ?otherAllocation ex:hasInvestor ?investorProfile ;
                      ex:allocationPct ?otherAllocationPct .
    FILTER (xsd:decimal(?otherAllocationPct) > xsd:decimal(?allocationPct))
  }
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?purchaseDate
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:holdingId ?holdingId ;
                     ex:investmentName ?investmentName ;
                     ex:purchaseDate ?purchaseDate .
}
ORDER BY ASC(?purchaseDate)
LIMIT 5

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentName
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:hasInvestor ?investor ;
           ex:investmentTypeLiteral "mutual fund"^^xsd:string ;
           ex:investmentName ?investmentName .

  FILTER NOT EXISTS {
    ?cashFlow a ex:CashFlow ;
              ex:cashFlowType "redemption"^^xsd:string ;
              ex:hasInvestor ?investor .
  }
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (COUNT(?holding) AS ?transactionCount) (SUM(xsd:decimal(?dividends)) AS ?totalAmount)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName .
  ?holding a ex:PortfolioHolding ;
           ex:hasInvestor ?investor ;
           ex:dividends ?dividends .
}
GROUP BY ?investorName

PREFIX ex: <http://example.org/kg#>
