PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?newAllocationPct)) AS ?averageNewAllocationPct)
WHERE {
  ?scenarioRebalancing a ex:ScenarioRebalancing ;
                       ex:newAllocationPct ?newAllocationPct .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?cashFlowId) AS ?redemptionCount)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "Redemption" ;
            ex:hasInvestor ?investor .
  FILTER(CONTAINS(LCASE(STR(?investor)), "inv-008"))
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?currentValue)) AS ?totalHoldings)
WHERE {
  ?investorProfile a ex:InvestorProfile ;
                   ex:riskTolerance "Conservative" .
  ?portfolioHolding a ex:PortfolioHolding ;
                    ex:hasInvestor ?investorProfile ;
                    ex:currentValue ?currentValue .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?amount)) AS ?averageDividendCashFlow)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "dividend"^^xsd:string ;
            ex:amount ?amount .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?targetAmount)) AS ?averageTargetAmount)
WHERE {
  ?investmentGoal a ex:InvestmentGoal ;
                  ex:goalRiskId "Aggressive"^^xsd:string ;
                  ex:targetAmount ?targetAmount .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?amount)) AS ?averageDividendCashFlow)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:cashFlowType "dividend" ;
            ex:amount ?amount .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLiteral (SUM(xsd:decimal(?currentValue)) AS ?totalPortfolioValue)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:categoryLiteral ?categoryLiteral ;
                     ex:currentValue ?currentValue .
}
GROUP BY ?categoryLiteral

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investor) AS ?numberOfInvestors)
WHERE {
  ?portfolioHealth ex:riskScore "At Risk" ;
                    ex:hasInvestor ?investor .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName .

  FILTER NOT EXISTS {
    ?holding a ex:PortfolioHolding ;
             ex:hasInvestor ?investor ;
             ex:purchaseDate ?purchaseDate .

    BIND(xsd:date(?purchaseDate) AS ?date)
    FILTER(DATE(?date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 12 MONTH))
  }
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?assetCategory (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:hasAssetClass ?assetClass ;
           ex:currentValue ?currentValue .
  ?assetClass ex:categoryLiteral ?assetCategory .
}
GROUP BY ?assetCategory

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLiteral (SUM(xsd:decimal(?currentValue)) AS ?totalPortfolioValue)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:categoryLiteral ?categoryLiteral ;
                     ex:currentValue ?currentValue .
}
GROUP BY ?categoryLiteral
ORDER BY ASC(?totalPortfolioValue)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId (MAX(xsd:decimal(?dividends)) AS ?maxDividends)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:holdingId ?holdingId ;
                     ex:dividends ?dividends .
}
GROUP BY ?holdingId
ORDER BY DESC(?maxDividends)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?targetAmount)) AS ?averageTargetAmount)
WHERE {
  ?investmentGoal a ex:InvestmentGoal ;
                  ex:goalRiskId "Aggressive"^^xsd:string ;
                  ex:targetAmount ?targetAmount .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?changeDirection (AVG(xsd:decimal(?newAllocationPct)) AS ?averageRevisedAllocation)
WHERE {
  ?scenarioRebalancing a ex:ScenarioRebalancing ;
                       ex:newAllocationPct ?newAllocationPct ;
                       ex:triggeredAction ?triggeredAction .

  BIND(IF(?newAllocationPct > 0, "Increased", "Decreased") AS ?changeDirection)
}
GROUP BY ?changeDirection

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (MAX(xsd:decimal(?totalInvestment)) AS ?maxTotalInvestment)
WHERE {
  ?allocation a ex:SectorAllocation ;
              ex:sectorName ?sectorName ;
              ex:totalInvestment ?totalInvestment .
}
GROUP BY ?sectorName

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year (MAX(xsd:decimal(?totalInvestment)) AS ?highestInvestment)
WHERE {
  VALUES ?year { "2022"^^xsd:string "2023"^^xsd:string "2024"^^xsd:string }
  ?allocation a ex:SectorAllocation ;
              ex:totalInvestment ?totalInvestment ;
              ex:purchaseDate ?purchaseDate .
  FILTER (CONTAINS(?purchaseDate, ?year))
}
GROUP BY ?year
ORDER BY DESC(?highestInvestment)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (SUM(xsd:decimal(?goldValue)) AS ?totalGoldInvestment)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:investorName ?investorName ;
            ex:hasHolding ?holding .
  ?holding a ex:PortfolioHolding ;
           ex:investmentTypeLiteral "Gold"^^xsd:string ;
           ex:currentValue ?goldValue .
}
GROUP BY ?investorName
ORDER BY ASC(?totalGoldInvestment)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (MAX(xsd:decimal(?totalInvestment)) AS ?maxTotalInvestment)
WHERE {
  ?allocation a ex:SectorAllocation ;
              ex:sectorName ?sectorName ;
              ex:totalInvestment ?totalInvestment .
}
GROUP BY ?sectorName

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?investor) AS ?count)
WHERE {
  ?investor a ex:InvestorProfile ;
            ex:hasHolding ?holding .
  ?holding a ex:PortfolioHolding ;
           ex:investmentTypeLiteral "Gold"^^xsd:string .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?source (COUNT(?cashFlowId) AS ?transactionCount)
WHERE {
  ?cashFlow a ex:CashFlow ;
            ex:source ?source ;
            ex:cashFlowId ?cashFlowId .
}
GROUP BY ?source
ORDER BY DESC(?transactionCount)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?holdingDuration)) AS ?averageHoldingDuration)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:hasInvestor "INV-012"^^xsd:string ;
                     ex:purchaseDate ?purchaseDate .

  BIND(DATEDIFF("day", xsd:date(?purchaseDate), CURRENT_DATE) AS ?holdingDuration)
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor (AVG(xsd:decimal(?holdingDuration)) AS ?averageHoldingDuration)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:hasInvestor ?investor ;
                     ex:purchaseDate ?purchaseDate .

  BIND(DATEDIFF("day", xsd:date(?purchaseDate), CURRENT_DATE) AS ?holdingDuration)
}
GROUP BY ?investor

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentType (SUM(xsd:decimal(?currentValue)) AS ?totalCurrentValue)
WHERE {
  ?portfolioHolding rdf:type ex:PortfolioHolding ;
                    ex:hasInvestmentType ?investmentType ;
                    ex:currentValue ?currentValue .
}
GROUP BY ?investmentType
ORDER BY DESC(?totalCurrentValue)
LIMIT 1

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?targetAmount)) AS ?averageTargetAmount)
WHERE {
  ?investmentGoal a ex:InvestmentGoal ;
                  ex:description "Aggressive"^^xsd:string ;
                  ex:targetAmount ?targetAmount .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(xsd:decimal(?currentValue)) AS ?totalHoldings)
WHERE {
  ?investorProfile a ex:InvestorProfile ;
                   ex:riskTolerance "Moderate" .
  ?portfolioHolding a ex:PortfolioHolding ;
                    ex:hasInvestor ?investorProfile ;
                    ex:currentValue ?currentValue .
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName ?returnsPct ?purchaseDate
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:returnsPct ?returnsPct ;
                     ex:purchaseDate ?purchaseDate ;
                     ex:investmentName ?investmentName ;
                     ex:holdingId ?holdingId .

  FILTER (xsd:decimal(?returnsPct) < 0)
  FILTER (YEAR(CURRENT_DATE()) - YEAR(xsd:date(?purchaseDate)) <= 1)
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorName (SUM(xsd:decimal(?taxesPaid)) AS ?totalTaxesPaid)
WHERE {
  ?portfolioHolding a ex:PortfolioHolding ;
                     ex:hasSector ?sector ;
                     ex:taxesPaid ?taxesPaid .

  ?sector a ex:Sector ;
          ex:sectorName ?sectorName .
}
GROUP BY ?sectorName

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName (SUM(xsd:decimal(?withdrawalAmount)) AS ?totalWithdrawals) (SUM(xsd:decimal(?depositAmount)) AS ?totalDeposits) 
       (IF(?totalDeposits = 0, "N/A", xsd:decimal(?totalWithdrawals) / xsd:decimal(?totalDeposits)) AS ?withdrawalToDepositRatio)
WHERE {
  ?cashFlow ex:hasInvestor ?investorProfile.
  ?investorProfile ex:investorName ?investorName.

  OPTIONAL {
    ?withdrawalCashFlow ex:hasInvestor ?investorProfile;
                        ex:cashFlowType "Withdrawal";
                        ex:amount ?withdrawalAmount.
  }

  OPTIONAL {
    ?depositCashFlow ex:hasInvestor ?investorProfile;
                      ex:cashFlowType "Deposit";
                      ex:amount ?depositAmount.
  }
}
GROUP BY ?investorName
